"""Source points 105–108 with measured triangles, the football goal and two surveying configurations."""
import argparse
import json
from math import acos, degrees, sqrt
from coordinate_curves import graph
from triangle_sine_area import ROOT, BOOK, area, triangle

OUT=ROOT/'geometry-course/textbook/data/triangle-relations.json'


def triangle_points(title,points,*,circle=None):
    return graph(title,points,edges=[('A','B'),('B','C'),('C','A')],circle=circle,radius_line=bool(circle))


def angles():
    main=triangle_points('Треугольник с катетами 3 и 4',{'A':(0,0),'B':(4,0),'C':(0,3)})
    circum=triangle_points('Диаметр описанной окружности',{'A':(0,0),'B':(4,0),'C':(0,3),'K':(2,1.5)},circle=('K',2.5))
    scaled=triangle_points('Удвоенные стороны и диаметр',{'A':(0,0),'B':(8,0),'C':(0,6),'K':(4,3)},circle=('K',5))
    return area(105,None,[277],'Докажи теорему синусов. Какая величина равна отношению стороны треугольника к синусу противолежащего угла?',
        'Из 2S=bc sin A=ca sin B=ab sin C делением на abc получаем sin A/a=sin B/b=sin C/c. Все величины положительны, поэтому a/sin A=b/sin B=c/sin C. Каждое отношение равно диаметру 2R описанной окружности.',
        'Запиши площадь тремя способами. Каждую сторону сопоставь углу у противоположной вершины.',
        [('Запиши три площади','Обозначь BC=a, CA=b, AB=c. Например, у прямоугольного треугольника с катетами 3 и 4 гипотенуза 5 лежит против прямого угла. Площадь 6 находится через любую пару сторон.','В произведении bc используется угол A.'),
         ('Получи пропорцию','После деления равенств для 2S на abc остаются дроби sin A/a, sin B/b, sin C/c. В примере 5/sin 90°=5; 3/(3/5)=5 и 4/(4/5)=5. Описанная окружность имеет диаметр 5.','Каждая появляется со своим противолежащим углом.'),
         ('Измени размер фигуры','Увеличь все стороны вдвое. Синусы останутся прежними, отношение сторон к синусам и диаметр вырастут до 10.','Для подобных треугольников синусы одинаковы, диаметры пропорциональны сторонам.')],[main,circum,scaled],
        [('Чему равен диаметр описанной окружности в треугольнике 3–4–5?','5','Гипотенуза прямоугольного треугольника служит диаметром.'),('Каков новый диаметр для катетов 6 и 8?','10','Коэффициент подобия равен двум.')],title='Теорема синусов')


def cosines():
    views=[triangle('Угол 60° между сторонами 3, 4','CBA',3,4,60),triangle('Тупой включённый угол 120°','CBA',3,4,120),triangle('Прямой включённый угол','CBA',3,4,90)]
    return area(106,None,[277,278],'Выведи квадрат длины стороны AB по сторонам CA=b, CB=a и углу C=γ. Как меняется вывод для тупого включённого угла?',
        'Пусть C=(0;0), B=(a;0), A=(b cos γ;b sin γ). По формуле расстояния AB²=(b cos γ−a)²+(b sin γ)²=a²+b²−2ab cos γ. Для тупого γ косинус отрицателен, поэтому квадрат AB больше a²+b².',
        'Проекция стороны CA на CB равна b cos γ и может быть отрицательной. Раскрой оба квадрата и используй сумму квадратов синуса и косинуса.',
        [('Положи сторону на ось','При a=3, b=4, γ=60° горизонтальная проекция CA равна 2. Формула даёт AB²=9+16−24·1/2=13.','Горизонтальная составляющая входит со знаком.'),
         ('Проверь тупой угол','При тех же сторонах и 120° косинус равен −1/2. Теперь AB²=25−24·(−1/2)=37. При раскрытии квадрата именно произведение −2ab cos γ зависит от знака.','Сторона напротив тупого угла длиннее, чем в соседней острой модели.'),
         ('Восстанови теорему Пифагора','Если γ=90°, косинус равен нулю. Квадрат гипотенузы 3²+4²=25, её длина 5.','Ту же формулу можно решать относительно косинуса, если известны все три стороны.')],views,
        [('Чему равен квадрат AB для 120° и сторон 3, 4?','37','Вычитание отрицательного произведения даёт прибавление 12.'),('Какова длина AB для нового угла 90°?','5','Возьми квадратный корень из 25.')],title='Теорема косинусов')


def solving():
    sas=triangle('Две стороны и угол между ними','CBA',3,4,90)
    asa=triangle('Одна сторона и два прилежащих угла','ABC',6,3*sqrt(2),45)
    sss=triangle_points('Три стороны 3, 4 и 5',{'A':(0,0),'B':(4,0),'C':(0,3)})
    # B and C are the bases of the goalposts, A is the player. AB=23, AC=24, BC=7.
    bx=0;cx=7;ax=(23**2+7**2-24**2)/14
    football=triangle_points('Игрок A и створ ворот BC=7',{'A':(sqrt(23**2-ax**2),ax),'B':(0,bx),'C':(0,cx)})
    return area(107,None,[278,279,280],'Как восстановить остальные стороны и углы по двум сторонам и включённому углу, по стороне с двумя прилежащими углами и по трём сторонам?',
        'По двум сторонам и углу между ними найдём третью сторону теоремой косинусов, затем угол по косинусу и последний угол из суммы 180°. По стороне и двум углам сначала находим третий угол, затем две стороны теоремой синусов. По трём сторонам два угла находим по косинусам и третий по сумме.',
        'Сначала запиши, какие элементы известны и какой угол противолежит каждой стороне. Проверяй сумму углов и неравенство треугольника.',
        [('Две стороны и включённый угол','При CB=3, CA=4, ∠C=90° сначала получаем AB=5. Затем cos A=4/5, а угол B дополняет A до 90°. По одному значению синуса острый и тупой углы могут различаться.','Результат arccos лежит между 0° и 180°.'),
         ('Сторона и два прилежащих угла','Пусть AB=6, ∠A=∠B=45°. Тогда ∠C=90°. По теореме синусов AC=BC=6 sin 45°=3√2.','Определи третий угол до деления на его синус.'),
         ('Три стороны и практический пример','Для длин 3, 4 и 5 косинус против стороны 5 равен нулю. В модели футбольных ворот AB=23 м, AC=24 м, BC=7 м. Угол обзора у A имеет cos A=(23²+24²−7²)/(2·23·24)=22/23. Это около 16°57′.','Малый угол напротив короткой стороны 7 — именно угол обзора ворот.')],[sas,asa,sss,football],
        [('Какова длина AB для катетов 3 и 4?','5','Сторона напротив прямого угла — гипотенуза.'),('Каков числитель сокращённой дроби cos A для ворот ширины 7?','22','Сократи 1056/1104 на 48.')],title='Решение треугольников')


def survey():
    near=graph('Доступное основание H дерева',{'A':(0,4),'H':(0,0),'B':(4,0)},edges=[('H','A'),('A','B'),('B','H')])
    far=graph('Две точки наблюдения по одну сторону',{'A':(0,4),'H':(0,0),'B':(4,0),'C':(8,0)},edges=[('H','A'),('A','B'),('A','C'),('H','C')])
    river=triangle_points('Базис AB и недоступная точка C',{'A':(0,0),'B':(8,0),'C':(4,4)})
    return area(108,None,[280,281],'Как определить высоту предмета и расстояние до недоступной точки по доступным отрезкам и измеренным углам?',
        'Для доступного основания H высота AH=HB·tg α. Если H недоступно, отметь B и C по одну сторону от H, где B ближе, BC=a, углы возвышения α>β. Тогда AH=a sin α sin β / sin(α−β). Для точки C за рекой при базисе AB=c и внутренних углах A=α, B=β расстояние AC=c sin β/sin(α+β).',
        'Сначала различи две схемы: наблюдения по одной прямой перед предметом и треугольник с доступным базисом. На первой схеме возникает разность углов, на второй — сумма.',
        [('Высота при доступном основании','Когда HB=4 и угол возвышения 45°, из прямоугольного треугольника AH=4·tg 45°=4.','Здесь HB измерено на земле.'),
         ('Высота по двум наблюдениям','Пусть B и C перед предметом, а B ближе. В треугольнике ABC угол при A равен α−β. По теореме синусов AB=a sin β/sin(α−β). Высота AH=AB sin α. На рисунке HB=4, HC=8; tan α=1, tan β=1/2, AH=4.','Угол при B внутри треугольника ABC смежен с углом возвышения α.'),
         ('Расстояние поперёк воды','Берём доступный базис AB=8 и измеряем α=β=45°. При C будет 90°, поэтому AC=8 sin 45°/sin 90°=4√2. В общем случае знаменатель sin(180°−α−β)=sin(α+β).','Расстояние AC лежит напротив β, базис AB напротив C.')],[near,far,river],
        [('Какова высота при HB=4 и угле возвышения 45°?','4','Тангенс 45° равен 1.'),('Каков угол C в новой схеме при α=β=45°?','90','Вычти два угла базиса из 180°.')],title='Измерительные работы')


def build():
    return {'bookId':BOOK,'lessons':[angles(),cosines(),solving(),survey()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    result=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==result
    else:OUT.write_text(result)
